// rimraf 6 uses promises/named exports; preserve temp 0.9.4 callback and sync APIs.
const rimrafApi = require('rimraf');
let rimraf = (target, options, callback) => {
  rimrafApi.rimraf(target, { glob: false, maxRetries: options.maxBusyTries })
    .then(() => callback(null), callback);
};
rimraf.sync = (target, options) => rimrafApi.rimrafSync(target, { glob: false, maxRetries: options.maxBusyTries });
